package net.civeira.phylax.features.document.templatevariable.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.tenant.domain.TenantReference;

class TemplateVariableChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_template_variable_change_set_builder() {
    TemplateVariableChangeSet one =
        new TemplateVariableChangeSet().uid("one").code("one").tenant(TenantReference.of("one"))
            .type("one").value("one").enabled(true).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getCode().get(), "Value must equals to the intial value");
    one.code("two");
    Assertions.assertEquals("two", one.getCode().get(), "Value must equals to the assigned value");
    one.unset("code");
    Assertions.assertFalse(one.getCode().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TenantReference.of("one"), one.getTenant().get(),
        "Value must equals to the intial value");
    one.tenant(TenantReference.of("two"));
    Assertions.assertEquals(TenantReference.of("two"), one.getTenant().get(),
        "Value must equals to the assigned value");
    one.unset("tenant");
    Assertions.assertFalse(one.getTenant().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getType().get(), "Value must equals to the intial value");
    one.type("two");
    Assertions.assertEquals("two", one.getType().get(), "Value must equals to the assigned value");
    one.unset("type");
    Assertions.assertFalse(one.getType().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getValue().get(), "Value must equals to the intial value");
    one.value("two");
    Assertions.assertEquals("two", one.getValue().get(), "Value must equals to the assigned value");
    one.unset("value");
    Assertions.assertFalse(one.getValue().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getEnabled().get(), "Value must equals to the intial value");
    one.enabled(false);
    Assertions.assertEquals(false, one.getEnabled().get(),
        "Value must equals to the assigned value");
    one.unset("enabled");
    Assertions.assertFalse(one.getEnabled().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
